    public static class DinoBuzzati
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "Chi ha dato tanto alla montagna, chi per la montagna ha rischiato con tanto accanimento la vita, a questo amore resterà legato per sempre.", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "Ciascuno di noi forse porta scritta in una recondita particella del corpo, la propria finale condanna. Ma perché andare determinatamente a disseppellirla?", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "E se l'idea di poter prolungare l'esistenza al nostro cane ci seduce non è solo perché gli vogliamo bene, ma anche per amore di noi stessi.", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "Il film ci rivela quanto abietto, crudele e stolto è l'uomo: è quindi una lezione di umiltà.", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "Io voglio ricordarmi di essere stato [...]. Divenire un'anima felice che ignora di essere stato Dino Buzzati, è una fregatura.", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "L'opportunismo e l'arrivismo filo-marxista dei miei colleghi mi fa venire il vomito, e come primo impulso mi fa diventare assertore della monarchia assoluta.", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "La solitudine si accresce quante più persone conosciamo.", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "Una cretinèria bell'e buona.", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "Una specie di demonio si aggira dunque per la città, invisibile, e sta forse preparandosi a nuovo sangue.", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "Cessati l'assalto al potere e la smania del predominio, si vide che dovunque si stabilivano automaticamente la giustizia e la pace.", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "E di innumerevoli afflizioni è generoso il mondo, ma i morsi dell'invidia sono tra le ferite più sanguinose, profonde, difficili, da rimarginare e complessivamente degne di pietà.", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "Guardava dinnanzi a sé i parchi, i campi, i boschi, le montagne, le misteriose montagne. Vendetta, che inutile cosa.", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "Ogni vero dolore viene scritto su lastre di una sostanza misteriosa al paragone della quale il granito è burro. E non basta una eternità per cancellarlo.", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "Niente? Proprio niente rimane. Di mia mamma non esiste più nulla? Chissà. Di quando in quando, specialmente nel pomeriggio, se mi trovo solo, provo una sensazione strana.", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "Nel sogno c'è sempre qualcosa di assurdo e confuso, non ci si libera mai della vaga sensazione ch'è tutto falso, che un bel momento ci si dovrà svegliare.", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "No, non è specialmente grande rispetto ad altri giovani compagni, ma in un certo senso è magnifico, lui che è una delle bestie più brutte del mondo.", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "Che peso, la presenza di Dio per chi non la desidera.", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "La luna [...] la placida abitatrice delle nostre notti, propizia agli incantesimi d'amore, discreta amica al cui lume favoloso le catapecchie diventavano castelli.", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "Le donne sono famose per costruir romanzi inverosimili.", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "È la pace di colui che si sente in armonia con la massa che lo attornia. Oppure è l'inquietudine, il disagio, lo smarrimento di chi si allontana dalla norma.", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "Anche il più nobile sentimento si atrofizza e si dissolve a poco a poco, se nessuno intorno ne fa più caso. È triste dirlo, ma a desiderare il Paradiso non si può essere soli.", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "La consolazione, la felicità era tale che il modo di raggiungerla non aveva più alcuna importanza.", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "Lui si ricordò di una Madonna di Antonello da Messina. Il taglio del volto e la bocca erano identici. La madonna aveva più dolcezza, certo. Ma lo stesso stampo netto e genuino.", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "No. Lui la amava per se stessa, per quello che rappresentava di femmina, di capriccio, di giovinezza, di genuino popolana, di malizia, di inverecondia, di sfrontatezza, di libertà, di mistero.", Author = "Dino Buzzati" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Dino_Buzzati", Text = "Era molto più delicato e tenero di quanto si credesse. Era fatto di quell'impalpabile sostanza che volgarmente si chiama favola o illusione: anche se vero.", Author = "Dino Buzzati" },
        };
    }
